// ---------------------------------------------------------------------------
// Golden vector tests.
//
// The fixture at protocol/golden_vectors.bin is the single source of truth for
// the wire format. It is generated by tools/gen_golden_vectors.py and committed
// to the repository. Nobody edits it by hand.
//
// Two tests depend on it:
//   * This one (C++): encoding a known state produces bytes identical to the
//     fixture, byte for byte.
//   * The C# decoder test (M5): decoding the fixture yields the known values.
//
// If either implementation drifts, one of the two tests fails in CI. That is
// the entire point: a shared document is not a guarantee, a shared fixture
// verified on both sides is.
// ---------------------------------------------------------------------------

#include <gtest/gtest.h>

#include <array>
#include <cstdint>
#include <fstream>
#include <vector>

#include "protocol/telemetry_frame.hpp"

#ifndef FSE_GOLDEN_VECTORS_PATH
// Fallback for tools that compile this file without CMake (e.g. the
// cross-compiler warning sweep). The real path comes from CMake.
#    define FSE_GOLDEN_VECTORS_PATH "../../../../../protocol/golden_vectors.bin"
#endif

namespace fse
{
namespace protocol
{
namespace
{

std::vector<std::uint8_t> read_file(const char* path)
{
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    if (!file)
    {
        return {};
    }
    const auto size = file.tellg();
    file.seekg(0, std::ios::beg);
    std::vector<std::uint8_t> data(static_cast<std::size_t>(size));
    file.read(reinterpret_cast<char*>(data.data()), size);
    return data;
}

TEST(GoldenVectors, FileExistsAndHasTheRightSize)
{
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_FALSE(data.empty()) << "golden_vectors.bin not found at " << FSE_GOLDEN_VECTORS_PATH;
    EXPECT_EQ(data.size(), 10U * kFrameSize) << "expected 10 frames of 84 bytes";
}

TEST(GoldenVectors, Frame0DecodesSuccessfully)
{
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_GE(data.size(), kFrameSize);

    TelemetryFrame frame{};
    const bool     ok = decode(data.data(), frame);
    EXPECT_TRUE(ok) << "frame 0 (nominal cruise) should have a valid CRC";

    EXPECT_EQ(frame.magic, kMagic);
    EXPECT_EQ(frame.version, kProtocolVersion);
    EXPECT_EQ(frame.aircraft_id, 1U);
    EXPECT_EQ(frame.sequence, 1000U);
    EXPECT_EQ(frame.timestamp_ns, 10000000000ULL);
    EXPECT_EQ(frame.phase, 4U); // kCruise
    EXPECT_FLOAT_EQ(frame.airspeed_mps, 105.0F);
    EXPECT_FLOAT_EQ(frame.altitude_m, 900.0F);
}

TEST(GoldenVectors, CorruptedFrameFailsCrc)
{
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_GE(data.size(), 10U * kFrameSize);

    // The last frame has a corrupted payload (airspeed field flipped).
    const std::uint8_t* last_frame = data.data() + (9 * kFrameSize);

    TelemetryFrame frame{};
    const bool     ok = decode(last_frame, frame);
    EXPECT_FALSE(ok) << "the corrupted frame must fail the CRC check";
}

TEST(GoldenVectors, AllCleanFramesDecodeSuccessfully)
{
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_EQ(data.size(), 10U * kFrameSize);

    for (std::size_t i = 0; i < 9; ++i)
    {
        TelemetryFrame frame{};
        const bool     ok = decode(data.data() + (i * kFrameSize), frame);
        EXPECT_TRUE(ok) << "frame " << i << " should have a valid CRC";
    }
}

TEST(GoldenVectors, EncodeMatchesGoldenBytes)
{
    // The strongest assertion: encoding a known state produces bytes identical
    // to the fixture. This is the test that makes the C++ implementation
    // accountable to the shared contract.
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_GE(data.size(), kFrameSize);

    // Reconstruct frame 0 from the known values and encode it.
    TelemetryFrame frame{};
    frame.magic              = kMagic;
    frame.version            = kProtocolVersion;
    frame.aircraft_id        = 1U;
    frame.sequence           = 1000U;
    frame.timestamp_ns       = 10000000000ULL;
    frame.phase              = 4U;
    frame.status_flags       = 0U;
    frame.airspeed_mps       = 105.0F;
    frame.altitude_m         = 900.0F;
    frame.vertical_speed_mps = 0.0F;
    frame.heading_deg        = 90.0F;
    frame.pitch_deg          = 2.5F;
    frame.roll_deg           = 0.0F;
    frame.engine_temp_c[0]   = 620.0F;
    frame.engine_temp_c[1]   = 625.0F;
    frame.engine_temp_c[2]   = 630.0F;
    frame.engine_temp_c[3]   = 635.0F;
    frame.fuel_press_kpa     = 42.0F;
    frame.oil_press_kpa      = 38.0F;
    frame.accel_x_mps2       = 0.0F;
    frame.accel_y_mps2       = 9.81F;
    frame.accel_z_mps2       = 0.0F;

    std::array<std::uint8_t, kFrameSize> buffer{};
    encode(frame, buffer.data());

    for (std::size_t i = 0; i < kFrameSize; ++i)
    {
        EXPECT_EQ(buffer[i], data[i]) << "byte " << i << " differs";
    }
}

TEST(GoldenVectors, RoundTripAllCleanFrames)
{
    // Decode each clean frame and re-encode it. The bytes must be identical.
    const auto data = read_file(FSE_GOLDEN_VECTORS_PATH);
    ASSERT_EQ(data.size(), 10U * kFrameSize);

    for (std::size_t i = 0; i < 9; ++i)
    {
        TelemetryFrame frame{};
        ASSERT_TRUE(decode(data.data() + (i * kFrameSize), frame)) << "frame " << i;

        std::array<std::uint8_t, kFrameSize> buffer{};
        encode(frame, buffer.data());

        for (std::size_t j = 0; j < kFrameSize; ++j)
        {
            EXPECT_EQ(buffer[j], data[i * kFrameSize + j])
                << "frame " << i << " byte " << j << " differs after round-trip";
        }
    }
}

} // namespace
} // namespace protocol
} // namespace fse